get_task_by_name.afterResponse:
var tasks = response.tasks;
var page = 0;
while (tasks && tasks.length > 0) {
  var match = tasks.find((task) => task.name === inputs.task_name);
  if (match) return match;
  page++;
  tasks = call({method: 'GET', url: '/list/' + encodeURIComponent(inputs.list_id) + '/task', query: {page: String(page), limit: '100'}}).tasks;
}
throw new Error('Task with name "' + inputs.task_name + '" not found in list "' + inputs.list_id + '".');

get_task_comments.afterResponse:
var seen = {};
var order = [];
var keep = (c) => { if (!(c.id in seen)) order.push(c.id); seen[c.id] = c; };
(response.comments || []).forEach(keep);
var page = response.comments || [];
var pages = 1;
while (page.length >= 25 && pages < 40) {
  var last = page[page.length - 1];
  page = call({method: 'GET', url: '/task/' + encodeURIComponent(inputs.task_id) + '/comment', query: {start: String(last.date), start_id: last.id}}).comments || [];
  pages += 1;
  var fresh = page.filter((c) => !(c.id in seen));
  if (fresh.length === 0) break;
  fresh.forEach(keep);
}
return Object.assign({}, response, {comments: order.map((id) => seen[id])});

